// 开发期只检任务真实资产与生命周期关键不变量；完整世界/存读/性能仍待统一节点。
#include "resident/domains/tasks/task_model.hpp"
#include <cassert>
#include <iostream>
using namespace hanmo::resident;
// 最小真人/物品上下文用于直接执行现有领域，不替代完整世界验收。
int main(){
 auto catalog=std::make_shared<CommonCatalog>();catalog->items.insert("grain",{"grain",1});catalog->items.insert("letter",{"letter",1});catalog->places.insert("market",{"market","town",{}});
 RoleDefinition role;role.id="issuer";role.initial_actor="giver";role.place_id="market";role.services={"accept_offer","report_offer","deliver_message"};catalog->roles.insert(role.id,role);
 CommonState seed;seed.identity.tick=10;seed.next_instance_id=1;for(auto id:{"player","giver","guardee"}){ActorRecord actor;actor.id=id;actor.alive=true;actor.available=true;actor.hp=100;actor.wallet_id="cash:"+actor.id;actor.inventory_id="bag:"+actor.id;actor.location=SettlementLocation{"town","market"};seed.actors.insert(id,actor);seed.wallets.insert(actor.wallet_id,{actor.wallet_id,{Owner::Kind::actor,id,{}},100,{}});seed.inventories.insert(actor.inventory_id,{actor.inventory_id,{Owner::Kind::actor,id,{}},100,0,{}});}
 CommonStore common(std::move(seed),catalog);TaskCatalog tasks_catalog;TaskDefinition offer;offer.id="grain_offer";offer.template_id="procurement";offer.accept_role="issuer";offer.report_role="issuer";offer.issuer={Owner::Kind::actor,"giver",{}};offer.funding_wallet="cash:giver";offer.budget=20;offer.reward=8;offer.accept_ticks=1;offer.deadline_ticks=4;offer.on_unavailable="wait_or_leave";offer.goal.item_id="grain";offer.goal.quantity=3;offer.goal.receiver_role="issuer";tasks_catalog.offers.insert(offer.id,offer);
 TaskState tasks;SocialState social;InteractionState interaction;interaction.knowledge.push_back({"player",{{"grain_offer",0,{"prop","board"}}}});InteractionCatalog ic;ic.common=catalog;InteractionAccess access;access.resolve_location=[&](const StableId& id){return common.actor(id)->location;};access.battle_occupied=[](const auto&){return false;};access.role=[](const auto&){return std::optional<RoleAssignmentView>{{"giver",true}};};
 TaskCommand command{"accept_offer","grain_offer",{"market","giver","issuer"}};auto q=preview_task(common,tasks,tasks_catalog,*catalog,interaction,ic,access,"player",command);assert(q.ok&&q.value.duration==1);
 auto action_id=common.next_id("action");ActionCoreView action{action_id.value,"accept_offer","player",{"player","giver"},10,1};assert(start_task_action(common,tasks,tasks_catalog,action,command,q.value).ok);auto task_id=tasks.tasks.order().front();assert(common.wallet("cash:giver")->balance==100);assert(common.spendable("cash:giver").value==80);
 auto end=finish_task_action(common,tasks,social,tasks_catalog,interaction,ic,access,action,11);assert(end.ok&&end.value.success&&end.value.task_id==task_id);tasks.actions.erase(action.id);assert(common.wallet("cash:giver")->balance==80);assert(common.wallet(tasks.tasks.find(task_id)->budget_wallet_id)->balance==20);assert(task_procurement_authorized(tasks,tasks_catalog,"player",task_id,"grain"));
 assert(common.apply_resources({{AddLot{"bag:player","grain",3,{Owner::Kind::task,task_id,{}},{}}},{}}).ok);command.kind="report_offer";q=preview_task(common,tasks,tasks_catalog,*catalog,interaction,ic,access,"player",command);assert(q.ok&&q.value.reward==8);action_id=common.next_id("action");action={action_id.value,"report_offer","player",{"player","giver"},10,1};assert(start_task_action(common,tasks,tasks_catalog,action,command,q.value).ok);end=finish_task_action(common,tasks,social,tasks_catalog,interaction,ic,access,action,11);assert(end.ok);tasks.actions.erase(action.id);assert(tasks.tasks.find(task_id)->status=="success");assert(common.wallet("cash:player")->balance==128);assert(common.wallet("cash:giver")->balance==72);assert(common.count("bag:giver","grain",{{Owner::Kind::actor,"giver",{}}}).value==3);assert(social_trust(social,"giver","player")==4);
 auto serialized=encode_task_state(tasks);auto fields=std::get<BoundaryValue::Dict>(serialized.data);for(auto& f:fields)if(f.first=="action_params")f.first="actions";auto decoded=decode_task_seed(BoundaryValue{fields});assert(decoded.ok&&decoded.value.tasks.size()==1&&decoded.value.tasks.find(task_id)->settlement_id==tasks.tasks.find(task_id)->settlement_id);
 std::cout<<"task_development: escrow, settlement, source ownership, relationship and typed codec passed\n";
}
